import{_ as a,c as t,b as s,o as e}from"./app-90veb4I1.js";const p={};function l(i,n){return e(),t("div",null,n[0]||(n[0]=[s(`<h2 id="arthimetric-operations" tabindex="-1"><a class="header-anchor" href="#arthimetric-operations"><span>Arthimetric Operations</span></a></h2><p>These functions are used to perform arithmetic operations on arrays.</p><h3 id="_1-mad-add-a-b" tabindex="-1"><a class="header-anchor" href="#_1-mad-add-a-b"><span>1. <code>mad.add(a, b)</code></span></a></h3><p>Adds two arrays element-wise:</p><table><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Type</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">a, b</td><td style="text-align:center;">Array</td><td style="text-align:center;">Arrays of the same shape</td></tr><tr><td style="text-align:center;">Returns</td><td style="text-align:center;">Array</td><td style="text-align:center;">Resulting array after addition</td></tr></tbody></table><p><strong>Example</strong>:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> add <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token function">add</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// Result: [4, 6]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-mad-subtract-a-b" tabindex="-1"><a class="header-anchor" href="#_2-mad-subtract-a-b"><span>2. <code>mad.subtract(a, b)</code></span></a></h3><p>Subtracts the second array from the first, element-wise:</p><table><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Type</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">a, b</td><td style="text-align:center;">Array</td><td style="text-align:center;">Arrays of the same shape</td></tr><tr><td style="text-align:center;">Returns</td><td style="text-align:center;">Array</td><td style="text-align:center;">Resulting array after subtraction</td></tr></tbody></table><p><strong>Example</strong>:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> subtract <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token function">subtract</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">5</span><span class="token punctuation">,</span> <span class="token number">6</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// Result: [3, 3]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-mad-multiply-a-b" tabindex="-1"><a class="header-anchor" href="#_3-mad-multiply-a-b"><span>3. <code>mad.multiply(a, b)</code></span></a></h3><p>Multiplies two arrays element-wise:</p><table><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Type</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">a, b</td><td style="text-align:center;">Array</td><td style="text-align:center;">Arrays of the same shape</td></tr><tr><td style="text-align:center;">Returns</td><td style="text-align:center;">Array</td><td style="text-align:center;">Resulting array after multiplication</td></tr></tbody></table><p><strong>Example</strong>:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> multiply <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token function">multiply</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">4</span><span class="token punctuation">,</span> <span class="token number">5</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// Result: [8, 15]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-mad-divide-a-b" tabindex="-1"><a class="header-anchor" href="#_4-mad-divide-a-b"><span>4. <code>mad.divide(a, b)</code></span></a></h3><p>Divides the first array by the second, element-wise:</p><table><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Type</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">a, b</td><td style="text-align:center;">Array</td><td style="text-align:center;">Arrays of the same shape</td></tr><tr><td style="text-align:center;">Returns</td><td style="text-align:center;">Array</td><td style="text-align:center;">Resulting array after division</td></tr></tbody></table><p><strong>Example</strong>:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> divide <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token function">divide</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">10</span><span class="token punctuation">,</span> <span class="token number">20</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">5</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// Result: [5, 4]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-mad-pow-a-b" tabindex="-1"><a class="header-anchor" href="#_5-mad-pow-a-b"><span>5. <code>mad.pow(a, b)</code></span></a></h3><p>Raises each element in a to the power of the corresponding element or scalar <code>b</code>:</p><table><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Type</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">a</td><td style="text-align:center;">Array</td><td style="text-align:center;">Base values</td></tr><tr><td style="text-align:center;">b</td><td style="text-align:center;">Array or number</td><td style="text-align:center;">Exponents</td></tr><tr><td style="text-align:center;">Returns</td><td style="text-align:center;">Array</td><td style="text-align:center;">Array of exponentiated values</td></tr></tbody></table><p><strong>Example</strong>:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> pow <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token function">pow</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// Result: [4, 9]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,27)]))}const r=a(p,[["render",l]]),o=JSON.parse('{"path":"/om-functions/arithmetic-operations.html","title":"Arithmetic Operations","lang":"en-US","frontmatter":{"lang":"en-US","title":"Arithmetic Operations","description":"This page will guide you on how to install openmadness"},"headers":[{"level":2,"title":"Arthimetric Operations","slug":"arthimetric-operations","link":"#arthimetric-operations","children":[{"level":3,"title":"1. mad.add(a, b)","slug":"_1-mad-add-a-b","link":"#_1-mad-add-a-b","children":[]},{"level":3,"title":"2. mad.subtract(a, b)","slug":"_2-mad-subtract-a-b","link":"#_2-mad-subtract-a-b","children":[]},{"level":3,"title":"3. mad.multiply(a, b)","slug":"_3-mad-multiply-a-b","link":"#_3-mad-multiply-a-b","children":[]},{"level":3,"title":"4. mad.divide(a, b)","slug":"_4-mad-divide-a-b","link":"#_4-mad-divide-a-b","children":[]},{"level":3,"title":"5. mad.pow(a, b)","slug":"_5-mad-pow-a-b","link":"#_5-mad-pow-a-b","children":[]}]}],"git":{"updatedTime":1751456764000,"contributors":[{"name":"Dev-Liz","username":"Dev-Liz","email":"basseyelizabeth569@gmail.com","commits":1,"url":"https://github.com/Dev-Liz"}],"changelog":[{"hash":"a6376b6867019658f19d5f27afd0cae5c3b98baa","time":1751456764000,"email":"basseyelizabeth569@gmail.com","author":"Dev-Liz","message":"updated docs"}]},"filePathRelative":"om-functions/arithmetic-operations.md"}');export{r as comp,o as data};
